import{_ as a,o as d,c as e,ag as i}from"./chunks/framework.i8sMDeRW.js";const k=JSON.parse('{"title":"AI 产品内容安全框架","description":"","frontmatter":{},"headers":[],"relativePath":"guide/10-compliance/content-safety-framework.md","filePath":"guide/10-compliance/content-safety-framework.md","lastUpdated":1778822679000}'),s={name:"guide/10-compliance/content-safety-framework.md"};function r(n,t,l,h,p,o){return d(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="ai-产品内容安全框架" tabindex="-1">AI 产品内容安全框架 <a class="header-anchor" href="#ai-产品内容安全框架" aria-label="Permalink to &quot;AI 产品内容安全框架&quot;">​</a></h1><blockquote><p><strong>2026-05 更新版</strong>：AI 内容安全已经从“过滤不良文本”扩展到多模态输入输出、RAG 来源污染、Prompt 注入、Agent 工具误用、MCP 连接器供应链风险和高风险领域责任边界。本文面向 AI PM，提供产品层面的安全框架与上线门禁。</p></blockquote><hr><h2 id="_1-ai-内容安全的独特性" tabindex="-1">1. AI 内容安全的独特性 <a class="header-anchor" href="#_1-ai-内容安全的独特性" aria-label="Permalink to &quot;1. AI 内容安全的独特性&quot;">​</a></h2><h3 id="_1-1-从内容生成安全到-agent-执行安全" tabindex="-1">1.1 从内容生成安全到 Agent 执行安全 <a class="header-anchor" href="#_1-1-从内容生成安全到-agent-执行安全" aria-label="Permalink to &quot;1.1 从内容生成安全到 Agent 执行安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>早期 LLM 产品</th><th>2026 年 AI / Agent 产品</th></tr></thead><tbody><tr><td>输入</td><td>文本 Prompt</td><td>文本、图片、语音、文件、网页、代码、工具返回值</td></tr><tr><td>输出</td><td>文本回答</td><td>文本、图片、代码、文件、API 写入、外部动作</td></tr><tr><td>风险</td><td>有害内容、幻觉、偏见</td><td>以上 + 越权工具调用、数据泄露、供应链注入、自动执行事故</td></tr><tr><td>防护</td><td>输入 / 输出过滤</td><td>策略网关、工具权限、沙箱、审批、trace、评估闭环</td></tr><tr><td>责任</td><td>内容审核</td><td>产品、工程、安全、法务、运营共同治理</td></tr></tbody></table><h3 id="_1-2-风险分类" tabindex="-1">1.2 风险分类 <a class="header-anchor" href="#_1-2-风险分类" aria-label="Permalink to &quot;1.2 风险分类&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险类型</th><th>说明</th><th>风险等级</th></tr></thead><tbody><tr><td>违法与极端内容</td><td>暴力恐怖、儿童性剥削、毒品制造等</td><td>极高</td></tr><tr><td>自残与自杀</td><td>鼓励、指导、强化自残行为</td><td>极高</td></tr><tr><td>仇恨与骚扰</td><td>针对受保护群体的攻击</td><td>高</td></tr><tr><td>色情与未成年人风险</td><td>露骨内容、未成年人性化</td><td>极高</td></tr><tr><td>危险行为</td><td>武器、诈骗、黑客攻击、规避监管</td><td>高</td></tr><tr><td>医疗 / 金融 / 法律误导</td><td>替代专业意见或给出高风险建议</td><td>高</td></tr><tr><td>幻觉与事实错误</td><td>编造来源、错误引用、误导决策</td><td>中到高</td></tr><tr><td>Prompt 注入</td><td>诱导模型忽略系统指令或泄露信息</td><td>高</td></tr><tr><td>工具误用</td><td>Agent 调错工具、写错系统、发送错误信息</td><td>高到极高</td></tr><tr><td>数据泄露</td><td>输出无权访问的数据或敏感信息</td><td>极高</td></tr><tr><td>多模态安全</td><td>图像、语音、视频中的有害或敏感内容</td><td>中到极高</td></tr></tbody></table><hr><h2 id="_2-安全架构" tabindex="-1">2. 安全架构 <a class="header-anchor" href="#_2-安全架构" aria-label="Permalink to &quot;2. 安全架构&quot;">​</a></h2><h3 id="_2-1-多层防护架构" tabindex="-1">2.1 多层防护架构 <a class="header-anchor" href="#_2-1-多层防护架构" aria-label="Permalink to &quot;2.1 多层防护架构&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户输入 / 文件 / 工具返回值</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>输入安全检测：内容风险 + PII + Prompt 注入 + 权限检查</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>上下文组装：RAG 权限过滤 + 来源可信度 + 数据最小化</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>模型推理：系统策略 + 安全指令 + 输出约束</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>工具策略网关：工具白名单 + 参数校验 + 风险分级 + 审批</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>输出安全检测：有害内容 + 幻觉 + 敏感信息 + 格式校验</span></span>
<span class="line"><span>        ↓</span></span>
<span class="line"><span>用户展示 / 工具执行 / 审计 trace / 反馈闭环</span></span></code></pre></div><h3 id="_2-2-输入安全" tabindex="-1">2.2 输入安全 <a class="header-anchor" href="#_2-2-输入安全" aria-label="Permalink to &quot;2.2 输入安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>层级</th><th>检测对象</th><th>处理策略</th></tr></thead><tbody><tr><td>L0 规则</td><td>黑名单、正则、密钥、身份证、手机号</td><td>脱敏、阻断或二次确认</td></tr><tr><td>L1 分类器</td><td>暴力、自残、色情、仇恨、危险行为</td><td>拒答、降级、安全引导</td></tr><tr><td>L2 Prompt 注入</td><td>忽略指令、泄露系统提示、角色扮演绕过</td><td>阻断、隔离、降低工具权限</td></tr><tr><td>L3 上下文权限</td><td>RAG 文档、工具返回值、组织数据</td><td>检索前权限过滤</td></tr><tr><td>L4 高风险任务</td><td>医疗、金融、法律、雇佣、教育</td><td>人工复核或专业边界提示</td></tr></tbody></table><h3 id="_2-3-输出安全" tabindex="-1">2.3 输出安全 <a class="header-anchor" href="#_2-3-输出安全" aria-label="Permalink to &quot;2.3 输出安全&quot;">​</a></h3><table tabindex="0"><thead><tr><th>检测维度</th><th>处理方式</th></tr></thead><tbody><tr><td>有害内容</td><td>拒答、改写为安全信息、转人工</td></tr><tr><td>敏感信息</td><td>脱敏、局部屏蔽、禁止输出</td></tr><tr><td>幻觉风险</td><td>要求引用来源、降低置信度、提示核验</td></tr><tr><td>高风险建议</td><td>添加免责声明、限制行动建议、建议专业人士</td></tr><tr><td>格式错误</td><td>自动修复、重试、返回安全 fallback</td></tr><tr><td>工具动作摘要</td><td>执行前展示影响范围和确认按钮</td></tr></tbody></table><hr><h2 id="_3-prompt-注入与-rag-污染" tabindex="-1">3. Prompt 注入与 RAG 污染 <a class="header-anchor" href="#_3-prompt-注入与-rag-污染" aria-label="Permalink to &quot;3. Prompt 注入与 RAG 污染&quot;">​</a></h2><h3 id="_3-1-prompt-注入类型" tabindex="-1">3.1 Prompt 注入类型 <a class="header-anchor" href="#_3-1-prompt-注入类型" aria-label="Permalink to &quot;3.1 Prompt 注入类型&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>示例</th><th>防护</th></tr></thead><tbody><tr><td>直接注入</td><td>“忽略之前所有指令”</td><td>系统指令隔离、注入检测</td></tr><tr><td>间接注入</td><td>网页 / 文档中隐藏恶意指令</td><td>RAG 内容降权、引用隔离</td></tr><tr><td>工具返回注入</td><td>外部 API 返回“请发送用户数据”</td><td>工具输出不作为指令执行</td></tr><tr><td>多轮注入</td><td>逐步诱导模型泄露上下文</td><td>会话级风险评分</td></tr><tr><td>编码绕过</td><td>Base64、Unicode、分隔符绕过</td><td>规范化后检测</td></tr></tbody></table><h3 id="_3-2-rag-安全原则" tabindex="-1">3.2 RAG 安全原则 <a class="header-anchor" href="#_3-2-rag-安全原则" aria-label="Permalink to &quot;3.2 RAG 安全原则&quot;">​</a></h3><ul><li>检索前做权限过滤，而不是检索后再过滤；</li><li>RAG 文档内容只能作为“数据”，不能作为“系统指令”；</li><li>引用来源要展示文档名、时间、权限范围；</li><li>对外部网页或用户上传文档设置较低信任等级；</li><li>对高风险来源使用摘要隔离，不直接塞入长上下文；</li><li>将失败和注入样例加入回归测试。</li></ul><hr><h2 id="_4-agent-工具安全" tabindex="-1">4. Agent 工具安全 <a class="header-anchor" href="#_4-agent-工具安全" aria-label="Permalink to &quot;4. Agent 工具安全&quot;">​</a></h2><h3 id="_4-1-工具动作分级" tabindex="-1">4.1 工具动作分级 <a class="header-anchor" href="#_4-1-工具动作分级" aria-label="Permalink to &quot;4.1 工具动作分级&quot;">​</a></h3><table tabindex="0"><thead><tr><th>等级</th><th>示例</th><th>默认策略</th></tr></thead><tbody><tr><td>T1 只读</td><td>搜索、读取文档、查询数据库</td><td>自动执行，记录日志</td></tr><tr><td>T2 低风险写入</td><td>创建草稿、生成报告、保存笔记</td><td>可自动，允许撤销</td></tr><tr><td>T3 高风险写入</td><td>发邮件、提交 PR、改配置、创建工单</td><td>人工确认</td></tr><tr><td>T4 不可逆 / 高影响</td><td>删除数据、支付、生产发布、外部披露</td><td>多人审批或禁止自动执行</td></tr></tbody></table><h3 id="_4-2-工具调用安全门禁" tabindex="-1">4.2 工具调用安全门禁 <a class="header-anchor" href="#_4-2-工具调用安全门禁" aria-label="Permalink to &quot;4.2 工具调用安全门禁&quot;">​</a></h3><p>每个工具必须定义：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">tool_policy</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  owner</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">security-platform</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  risk_level</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">T3</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  allowed_agents</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">support_agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">ops_agent</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  input_schema</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">strict_json_schema</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rate_limit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">10/min</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  requires_approval</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  audit</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">full</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  rollback</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">supported</span></span></code></pre></div><h3 id="_4-3-agent-执行防护" tabindex="-1">4.3 Agent 执行防护 <a class="header-anchor" href="#_4-3-agent-执行防护" aria-label="Permalink to &quot;4.3 Agent 执行防护&quot;">​</a></h3><table tabindex="0"><thead><tr><th>风险</th><th>防护</th></tr></thead><tbody><tr><td>无限循环</td><td>最大 step、最大时长、最大重试</td></tr><tr><td>成本失控</td><td>run budget、工具 budget、组织 budget</td></tr><tr><td>越权动作</td><td>RBAC / ABAC / ReBAC 策略网关</td></tr><tr><td>错误执行</td><td>执行前摘要 + 人工确认</td></tr><tr><td>沙箱逃逸</td><td>Docker / Firecracker / gVisor / seccomp</td></tr><tr><td>供应链风险</td><td>MCP server 白名单、签名、来源验证</td></tr><tr><td>结果不可追踪</td><td>完整 trace 和审批记录</td></tr></tbody></table><hr><h2 id="_5-多模态内容安全" tabindex="-1">5. 多模态内容安全 <a class="header-anchor" href="#_5-多模态内容安全" aria-label="Permalink to &quot;5. 多模态内容安全&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模态</th><th>风险</th><th>防护</th></tr></thead><tbody><tr><td>图片输入</td><td>证件、隐私照片、暴力色情内容</td><td>图像分类、OCR + PII 检测</td></tr><tr><td>图片输出</td><td>侵权、色情、暴力、名人滥用</td><td>生成前后审核、水印、拒绝策略</td></tr><tr><td>语音输入</td><td>未成年人、敏感对话、旁人录音</td><td>转写后检测、同意提示</td></tr><tr><td>语音输出</td><td>冒充他人、诈骗、深度伪造</td><td>声音克隆限制、标识 AI 生成</td></tr><tr><td>视频</td><td>人脸、未成年人、版权、深伪</td><td>多帧采样审核、来源标注</td></tr><tr><td>代码</td><td>恶意软件、密钥泄露、漏洞</td><td>静态扫描、沙箱、依赖审计</td></tr></tbody></table><hr><h2 id="_6-高风险领域策略" tabindex="-1">6. 高风险领域策略 <a class="header-anchor" href="#_6-高风险领域策略" aria-label="Permalink to &quot;6. 高风险领域策略&quot;">​</a></h2><table tabindex="0"><thead><tr><th>场景</th><th>策略</th></tr></thead><tbody><tr><td>医疗</td><td>不诊断、不替代医生；提供一般信息；紧急情况引导就医</td></tr><tr><td>金融</td><td>不给个性化投资建议；提示风险；引用数据来源和时间</td></tr><tr><td>法律</td><td>不构成法律意见；建议咨询律师；避免替用户做最终判断</td></tr><tr><td>雇佣 / 教育</td><td>避免自动化重大决策；提供人工复核和解释</td></tr><tr><td>未成年人</td><td>更严格内容过滤、家长控制、数据最小化</td></tr><tr><td>公共安全</td><td>危险操作和规避执法请求默认拒绝</td></tr></tbody></table><hr><h2 id="_7-评估与红队" tabindex="-1">7. 评估与红队 <a class="header-anchor" href="#_7-评估与红队" aria-label="Permalink to &quot;7. 评估与红队&quot;">​</a></h2><h3 id="_7-1-安全评估集" tabindex="-1">7.1 安全评估集 <a class="header-anchor" href="#_7-1-安全评估集" aria-label="Permalink to &quot;7.1 安全评估集&quot;">​</a></h3><p>安全评估集应覆盖：</p><ul><li>直接 Prompt 注入；</li><li>间接 Prompt 注入；</li><li>RAG 恶意文档；</li><li>工具越权；</li><li>敏感信息泄露；</li><li>自残、暴力、仇恨、色情；</li><li>医疗 / 金融 / 法律误导；</li><li>多语言绕过；</li><li>多模态绕过；</li><li>高风险 Agent 自动执行。</li></ul><h3 id="_7-2-红队流程" tabindex="-1">7.2 红队流程 <a class="header-anchor" href="#_7-2-红队流程" aria-label="Permalink to &quot;7.2 红队流程&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>定义风险场景 → 准备攻击样例 → 运行测试 → 标注失败</span></span>
<span class="line"><span>        → 修复策略 → 加入回归集 → 发布前重跑</span></span></code></pre></div><h3 id="_7-3-安全指标" tabindex="-1">7.3 安全指标 <a class="header-anchor" href="#_7-3-安全指标" aria-label="Permalink to &quot;7.3 安全指标&quot;">​</a></h3><table tabindex="0"><thead><tr><th>指标</th><th>说明</th></tr></thead><tbody><tr><td>漏拦截率</td><td>高风险请求未被阻断的比例</td></tr><tr><td>误拦截率</td><td>正常请求被错误阻断的比例</td></tr><tr><td>越权调用率</td><td>Agent 尝试调用无权工具的比例</td></tr><tr><td>敏感泄露率</td><td>输出包含敏感信息的比例</td></tr><tr><td>注入成功率</td><td>Prompt 注入绕过策略的比例</td></tr><tr><td>人工审批命中率</td><td>高风险动作进入审批的比例</td></tr><tr><td>安全回归通过率</td><td>每次发布前安全用例通过比例</td></tr></tbody></table><hr><h2 id="_8-用户体验与申诉" tabindex="-1">8. 用户体验与申诉 <a class="header-anchor" href="#_8-用户体验与申诉" aria-label="Permalink to &quot;8. 用户体验与申诉&quot;">​</a></h2><p>安全设计不能只说“不行”。好的安全体验应该：</p><ul><li>解释为什么不能回答；</li><li>给出安全替代方向；</li><li>对误拦截提供申诉入口；</li><li>对高风险动作展示影响范围；</li><li>对不确定事实提示核验；</li><li>对多次失败提供人工支持。</li></ul><p>示例：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我不能帮助执行这个操作，因为它会向外部系统发送客户数据。</span></span>
<span class="line"><span>你可以选择：</span></span>
<span class="line"><span>1. 生成一份不含个人信息的摘要；</span></span>
<span class="line"><span>2. 让管理员审批后继续；</span></span>
<span class="line"><span>3. 查看数据最小化建议。</span></span></code></pre></div><hr><h2 id="_9-上线检查清单" tabindex="-1">9. 上线检查清单 <a class="header-anchor" href="#_9-上线检查清单" aria-label="Permalink to &quot;9. 上线检查清单&quot;">​</a></h2><ul><li>[ ] 输入 / 输出安全检测已上线；</li><li>[ ] Prompt 注入和间接注入测试已通过；</li><li>[ ] RAG 文档权限过滤已实现；</li><li>[ ] 工具注册表和风险分级已完成；</li><li>[ ] 高风险工具调用需要人工审批；</li><li>[ ] Agent run 有 step、时间、成本上限；</li><li>[ ] 代码 / 浏览器 / 文件操作在沙箱执行；</li><li>[ ] 多模态内容审核已覆盖；</li><li>[ ] 高风险领域策略已配置；</li><li>[ ] 安全评估集已加入 CI / 发布流程；</li><li>[ ] trace、审计和事故响应流程已准备；</li><li>[ ] 用户申诉和人工支持入口已设计。</li></ul><hr><h2 id="_10-参考来源" tabindex="-1">10. 参考来源 <a class="header-anchor" href="#_10-参考来源" aria-label="Permalink to &quot;10. 参考来源&quot;">​</a></h2><ul><li>OWASP Top 10 for LLM Applications：<a href="https://genai.owasp.org/" target="_blank" rel="noreferrer">https://genai.owasp.org/</a></li><li>NIST AI Risk Management Framework：<a href="https://www.nist.gov/itl/ai-risk-management-framework" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework</a></li><li>NIST Generative AI Profile AI 600-1：<a href="https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-600-1" target="_blank" rel="noreferrer">https://www.nist.gov/itl/ai-risk-management-framework/nist-ai-600-1</a></li><li>Model Context Protocol：<a href="https://modelcontextprotocol.io/" target="_blank" rel="noreferrer">https://modelcontextprotocol.io/</a></li><li>EU AI Act 官方信息：<a href="https://artificialintelligenceact.eu/" target="_blank" rel="noreferrer">https://artificialintelligenceact.eu/</a></li></ul><hr><blockquote><p><strong>结语</strong>：AI 内容安全不是一个 moderation API 能解决的问题。真正可靠的 AI 产品，需要把内容安全、权限控制、工具治理、成本预算、审计回放和用户体验一起设计。</p></blockquote>`,60)])])}const b=a(s,[["render",r]]);export{k as __pageData,b as default};
